cmds:
- block:
    - ansible.builtin.include_role: {name: deploy}
  rescue:
    - ansible.builtin.include_role: {name: rollback}
  always:
    - ansible.builtin.debug: {msg: "done"}

class FilterModule(object):
    def filters(self):
        return {'cidr_hosts': cidr_hosts}

{% for v in vhosts %}
server_name {{ v.name }};
{% endfor %}

{% for h in groups['db'] | sort %}
server {{ hostvars[h].ansible_host }}:5432;
{% endfor %}
